def testcase(*, id, tags=(), requires=(), timeout_s=60):
    def decorator(func):
        func.meta = {"id": id, "tags": set(tags), "requires":
set(requires), "timeout_s": timeout_s}
        REGISTRY.append(func)
        return func
    return decorator
@testcase(id="TC-101", tags=["smoke"], requires=["redfish"])
def test_power_state():
    return "PASS"
