**__init_subclass__** (3.6+) is the modern, simple hook that runs whenever a class is subclassed. It covers almost every use for which people used to write metaclasses, such as **plugin registration** and validating subclasses:

```code
class Check:
    registry = {}
    def __init_subclass__(cls, *, check_id, **kwargs):
        super().__init_subclass__(**kwargs)
        if check_id in Check.registry:
            raise TypeError(f"duplicate check id {check_id}")
        if not callable(getattr(cls, "run", None)):
            raise TypeError(f"{cls.__name__} must define run()")
        cls.check_id = check_id
        Check.registry[check_id] = cls
class FanCheck(Check, check_id="HW-FAN-01"):
    def run(self):
        return "PASS"
class PsuCheck(Check, check_id="HW-PSU-01"):
    def run(self):
        return "FAIL"
print({cid: c.__name__ for cid, c in Check.registry.items()})
print([Check.registry[cid]().run() for cid in sorted(Check.registry)])
try:
    class Broken(Check, check_id="HW-BAD-01"):
        pass
except TypeError as e:
    print("TypeError:", e)
