```code
import xml.etree.ElementTree as ET
from pathlib import Path
Path("parts").mkdir(exist_ok=True)
Path("parts/unit.xml").write_text(
    '<testsuite name="unit" tests="2" failures="0" errors="0"
skipped="0" time="0.5">'
    '<testcase classname="t" name="a" time="0.2"/><testcase
classname="t" name="b" time="0.3"/></testsuite>')
Path("parts/hw.xml").write_text(
    '<testsuites><testsuite name="hw" tests="1" failures="1"
errors="0" skipped="0" time="61.0">'
    '<testcase classname="h" name="power" time="61.0"><failure
message="no prompt"/></testcase>'
    '</testsuite></testsuites>')
def merge(paths, out):
    merged = ET.Element("testsuites")
    totals = dict.fromkeys(("tests", "failures", "errors", "skipped"),
0)
    for path in paths:
        root = ET.parse(path).getroot()
        suites = [root] if root.tag == "testsuite" else
root.findall("testsuite")
        for suite in suites:
            merged.append(suite)
            for key in totals:
                totals[key] += int(suite.get(key, 0))
    for key, value in totals.items():
        merged.set(key, str(value))
    ET.ElementTree(merged).write(out, encoding="utf-8",
xml_declaration=True)
    return totals
print(merge(sorted(Path("parts").glob("*.xml")), "merged.xml"))
print(len(ET.parse("merged.xml").getroot().findall("testsuite")),
"suites in merged.xml")
