    elif isinstance(node, list):
        for item in node:
            all_links_dfs(item, found)
    return found
def depth_bfs(root):
    """Count links per depth level using BFS."""
    levels, q = {}, deque([(root, 0)])
    while q:
        node, depth = q.popleft()
        if isinstance(node, dict):
            if "@odata.id" in node:
                levels[depth] = levels.get(depth, 0) + 1
            children = [v for k, v in node.items() if k !=
"@odata.id"]
        elif isinstance(node, list):
            children = node
        else:
            children = []
        for child in children:
            q.append((child, depth + (1 if isinstance(node, dict) else
0)))
    return levels
for link in all_links_dfs(redfish):
    print(link)
print("links per depth:", depth_bfs(redfish))
class Node:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right
def max_depth(n):
    return 0 if n is None else 1 + max(max_depth(n.left),
max_depth(n.right))
def is_bst(n, lo=float("-inf"), hi=float("inf")):
    if n is None:
        return True
    return lo < n.val < hi and is_bst(n.left, lo, n.val) and
is_bst(n.right, n.val, hi)
tree = Node(40, Node(20, Node(10), Node(30)), Node(60, None,
Node(70)))
print("max depth:", max_depth(tree), "| valid BST:", is_bst(tree))
