```code
class TokenBucket:
    def __init__(self, rate_per_s, capacity, clock):
        self.rate, self.capacity, self.clock = rate_per_s, capacity,
clock
        self.tokens = capacity
        self.last = clock()
    def allow(self):
        now = self.clock()
        self.tokens = min(self.capacity, self.tokens + (now -
self.last) * self.rate)
        self.last = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False
