                raise RuntimeError("circuit open")
            self.opened_at = None              # half-open: allow one
trial
            self.failures = self.max_failures - 1
        try:
            result = func(*args)
        except Exception:
            self.failures += 1
            if self.failures >= self.max_failures:
                self.opened_at = self.clock()
            raise
        self.failures = 0
        return result
