    def raw(self, netfn: int, cmd: int, data: bytes = b"") ->
ipmi.IpmiResponse:
        if (netfn, cmd) == (ipmi.NETFN_APP, ipmi.APP_GET_DEVICE_ID):
            if data:
                return ipmi.IpmiResponse(0xC7, b"")
            # device id 0x20, rev 1 + provides SDRs, fw 2.15, IPMI 2.0,
            # manufacturer 0x00A0A0 (fictional), product 0x0001
            return ipmi.IpmiResponse(0x00, bytes([0x20, 0x81, 0x02, 0x15,
0x02, 0xBF,
                                                  0xA0, 0xA0, 0x00, 0x01,
0x00]))
        if (netfn, cmd) == (ipmi.NETFN_CHASSIS, ipmi.CHASSIS_GET_STATUS):
            if data:
                return ipmi.IpmiResponse(0xC7, b"")
            state = 0x01 if self.w.power_on else 0x00
            state |= 0x40  # restore policy = always-on (0b10 in bits 6:5)
            return ipmi.IpmiResponse(0x00, bytes([state, 0x00, 0x00]))
        if (netfn, cmd) == (ipmi.NETFN_CHASSIS, ipmi.CHASSIS_CONTROL):
            if len(data) != 1:
                return ipmi.IpmiResponse(0xC7, b"")
            action = data[0] & 0x0F
