            elif action == 0x01:
                self.w.set_power(True)
            elif action in (0x02, 0x03):
                self.w.set_power(False)
                self.w.set_power(True)
            else:
                return ipmi.IpmiResponse(0xCC, b"")
            return ipmi.IpmiResponse(0x00, b"")
        return ipmi.IpmiResponse(0xC1, b"")
