import subprocess
def disk_usage_pct(mount: str) -> int:
    try:
        cp = subprocess.run(["df", "-P", mount], capture_output=True, text=True,
                            timeout=5, check=True)
    except subprocess.TimeoutExpired:
        raise RuntimeError(f"df timed out for {mount} (hung filesystem?)")
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"df failed rc={exc.returncode}: {exc.stderr.strip()}")
    line = cp.stdout.splitlines()[1]
    return int(line.split()[4].rstrip("%"))
