def validate_argv(argv: Sequence[str], allowed: frozenset = DEFAULT_ALLOWED) -> None:
    """Refuse empty, non-allow-listed or state-changing commands."""
    if not argv:
        raise CommandRefused("empty command")
    if not all(isinstance(a, str) for a in argv):
        raise CommandRefused("all arguments must be strings")
    program = Path(argv[0]).name
    if program not in allowed:
        raise CommandRefused(f"'{program}' is not in the approved command list")
    # Compare "--opt=value" forms by their option name as well.
    bad = FORBIDDEN_ARGS.intersection(a.split("=", 1)[0] for a in argv[1:])
    if program in {"systemctl", "journalctl", "dmesg"} and bad:
        raise CommandRefused(f"state-changing argument(s) refused: {sorted(bad)}")
class RealRunner:
    """Runs approved commands on the local machine."""
    def __init__(self, timeout_s: float = 10.0, allowed: frozenset = DEFAULT_ALLOWED):
        self.timeout_s = timeout_s
        self.allowed = allowed
    def run(self, argv: Sequence[str], timeout_s: Optional[float] = None) -> CommandResult:
        argv = list(argv)
        started = utc_now()
        try:
            validate_argv(argv, self.allowed)
        except CommandRefused as exc:
            log.warning("refused command %s: %s", argv, exc)
            return CommandResult(argv, None, started=started, error=f"refused: {exc}")
        resolved = shutil.which(argv[0])
        if resolved is None:
            return CommandResult(argv, None, started=started,
                                 error=f"command not found: {argv[0]}")
        limit = self.timeout_s if timeout_s is None else timeout_s
        t0 = time.monotonic()
        try:
            proc = subprocess.run(
                [resolved] + argv[1:],
                capture_output=True,
                text=True,
                errors="replace",
                timeout=limit,
                check=False,
                env={"LC_ALL": "C", "PATH": "/usr/sbin:/usr/bin:/sbin:/bin"},
            )
        except subprocess.TimeoutExpired as exc:
            out = exc.stdout.decode(errors="replace") if isinstance(exc.stdout, bytes) else
(exc.stdout or "")
            err = exc.stderr.decode(errors="replace") if isinstance(exc.stderr, bytes) else
(exc.stderr or "")
            return CommandResult(argv, None, out, err, started,
                                 round(time.monotonic() - t0, 3), True,
                                 f"timed out after {limit}s")
        except OSError as exc:  # permission denied, exec format error, ...
            return CommandResult(argv, None, started=started,
                                 duration_s=round(time.monotonic() - t0, 3),
                                 error=f"os error: {exc}")
        return CommandResult(argv, proc.returncode, proc.stdout, proc.stderr, started,
                             round(time.monotonic() - t0, 3))
class SimulatedRunner:
    """Returns canned results from a fixture file.
    Fixture format (JSON object keyed by the command line joined with spaces):
        {"uname -a": {"rc": 0, "stdout": "Linux sim 6.6.0 ...", "stderr": ""},
         "systemctl is-active bmcweb": {"rc": 3, "stdout": "failed\\n"},
         "journalctl -b -p err": {"timeout": true}}
    Unknown commands return rc=127 with an explanatory error, mimicking
    'command not found' so callers handle them like real missing tools.
    """
    def __init__(self, fixture: Dict[str, dict], allowed: frozenset = DEFAULT_ALLOWED):
        self.fixture = fixture
          self.allowed = allowed
          self.calls: List[List[str]] = []
      @classmethod
      def from_file(cls, path: Path) -> "SimulatedRunner":
          with Path(path).open(encoding="utf-8") as fh:
              return cls(json.load(fh))
      def run(self, argv: Sequence[str], timeout_s: Optional[float] = None) -> CommandResult:
          argv = list(argv)
          self.calls.append(argv)
          try:
              validate_argv(argv, self.allowed)
          except CommandRefused as exc:
              return CommandResult(argv, None, error=f"refused: {exc}")
          key = " ".join(argv)
          entry = self.fixture.get(key)
          if entry is None:
              return CommandResult(argv, 127, "", f"simulated: no fixture for '{key}'",
                                   error="command not available in simulation")
          if entry.get("timeout"):
              return CommandResult(argv, None, timed_out=True,
                                   error=f"timed out after {timeout_s or 'default'}s
  (simulated)")
          return CommandResult(argv, int(entry.get("rc", 0)), entry.get("stdout", ""),
                               entry.get("stderr", ""),
  duration_s=float(entry.get("duration_s", 0.01)))
