  """Diagnostic checks.
  Each check is a function taking (runner, config) and returning a CheckResult.
  Checks never raise for expected failures; run_all() additionally catches
  unexpected exceptions so one broken check cannot destroy the evidence
  gathered by the others.
  """
  from __future__ import annotations
  import logging
  import re
  import time
  from dataclasses import dataclass, field
  from typing import Callable, Dict, List
  from .runner import CommandResult, utc_now
  log = logging.getLogger(__name__)
  PASS, WARN, FAIL, SKIP, ERROR = "PASS", "WARN", "FAIL", "SKIP", "ERROR"
  SEVERITY = {PASS: 0, SKIP: 0, WARN: 1, FAIL: 2, ERROR: 3}
  @dataclass
  class CheckResult:
      name: str
      status: str
      detail: str
      started: str = field(default_factory=utc_now)
      duration_s: float = 0.0
      data: dict = field(default_factory=dict)
      evidence: List[dict] = field(default_factory=list)
    def add_evidence(self, res: CommandResult, max_chars: int = 20000) -> None:
        d = res.to_dict()
        for key in ("stdout", "stderr"):
            if len(d[key]) > max_chars:
                d[key] = d[key][:max_chars] + f"\n...[truncated {len(d[key]) - max_chars}
chars]"
        self.evidence.append(d)
# --------------------------------------------------------------------- helpers
def parse_df(text: str) -> List[dict]:
    """Parse 'df -P' output into a list of dicts (mount, used_pct, ...)."""
    rows = []
    for line in text.splitlines()[1:]:
        parts = line.split()
        if len(parts) < 6:
            continue
        pct = parts[4].rstrip("%")
        if not pct.isdigit():
            continue
        rows.append({"filesystem": parts[0], "used_pct": int(pct),
                     "mount": " ".join(parts[5:])})
    return rows
def parse_meminfo(text: str) -> Dict[str, int]:
    """Parse /proc/meminfo into {key: kB}."""
    out: Dict[str, int] = {}
    for line in text.splitlines():
        m = re.match(r"^(\w+(?:\(\w+\))?):\s+(\d+)", line)
        if m:
            out[m.group(1)] = int(m.group(2))
    return out
# ---------------------------------------------------------------------- checks
def check_connectivity(runner, cfg) -> CheckResult:
    hosts = cfg.get("ping_hosts", [])
    if not hosts:
        return CheckResult("connectivity", SKIP, "no ping_hosts configured")
    res = CheckResult("connectivity", PASS, "")
    down = []
    for host in hosts:
        r = runner.run(["ping", "-c", "2", "-W", "2", host], timeout_s=cfg["timeout_s"])
        res.add_evidence(r)
        if r.returncode is None and r.error and "not found" in r.error:
            return CheckResult("connectivity", SKIP, "ping is not installed on this system",
                               evidence=res.evidence)
        if not r.ok:
            down.append(host)
    res.data["unreachable"] = down
    if down:
        res.status = WARN   # ICMP may be blocked: a warning, not proof of failure
        res.detail = f"no ICMP reply from: {', '.join(down)}"
    else:
        res.detail = f"{len(hosts)} host(s) answered ping"
    return res
def check_services(runner, cfg) -> CheckResult:
    services = cfg.get("services", [])
    if not services:
        return CheckResult("services", SKIP, "no services configured")
    res = CheckResult("services", PASS, "")
    states = {}
    for svc in services:
        r = runner.run(["systemctl", "is-active", svc], timeout_s=cfg["timeout_s"])
        res.add_evidence(r)
        if r.error and r.returncode in (None, 127):
            states[svc] = "unknown"
        else:
            states[svc] = (r.stdout.strip() or "unknown")
    res.data["states"] = states
    bad = {s: st for s, st in states.items() if st != "active"}
    if all(st == "unknown" for st in states.values()):
        res.status, res.detail = SKIP, "service state unavailable (no systemd or no access)"
    elif bad:
        res.status = FAIL
        res.detail = "not active: " + ", ".join(f"{s}={st}" for s, st in bad.items())
    else:
        res.detail = f"all {len(services)} service(s) active"
    return res
def check_disk(runner, cfg) -> CheckResult:
    r = runner.run(["df", "-P"], timeout_s=cfg["timeout_s"])
    res = CheckResult("disk", PASS, "")
    res.add_evidence(r)
    if not r.ok:
        res.status, res.detail = ERROR, f"df failed: {r.error or r.stderr.strip()}"
        return res
    ignore = tuple(cfg.get("ignore_fs_prefixes", ["tmpfs", "devtmpfs", "overlay", "none"]))
    rows = [row for row in parse_df(r.stdout) if not row["filesystem"].startswith(ignore)]
    res.data["filesystems"] = rows
    warn, fail = cfg["disk_warn_pct"], cfg["disk_fail_pct"]
    worst = max((row["used_pct"] for row in rows), default=0)
    over_fail = [f"{x['mount']}={x['used_pct']}%" for x in rows if x["used_pct"] >= fail]
    over_warn = [f"{x['mount']}={x['used_pct']}%" for x in rows if warn <= x["used_pct"] <
fail]
    if over_fail:
        res.status, res.detail = FAIL, "above fail threshold: " + ", ".join(over_fail)
    elif over_warn:
        res.status, res.detail = WARN, "above warn threshold: " + ", ".join(over_warn)
    else:
        res.detail = f"{len(rows)} filesystem(s), highest usage {worst}%"
    return res
def check_memory(runner, cfg) -> CheckResult:
    r = runner.run(["cat", "/proc/meminfo"], timeout_s=cfg["timeout_s"])
    res = CheckResult("memory", PASS, "")
    res.add_evidence(r)
    if not r.ok:
        res.status, res.detail = ERROR, f"cannot read /proc/meminfo: {r.error or r.stderr.str
ip()}"
        return res
    mem = parse_meminfo(r.stdout)
    total, avail = mem.get("MemTotal"), mem.get("MemAvailable")
    if not total or avail is None:
        res.status, res.detail = SKIP, "MemTotal/MemAvailable not present"
        return res
    pct = round(100.0 * avail / total, 1)
    res.data = {"mem_total_kb": total, "mem_available_kb": avail, "available_pct": pct}
    if pct < cfg["mem_fail_available_pct"]:
        res.status = FAIL
    elif pct < cfg["mem_warn_available_pct"]:
        res.status = WARN
    res.detail = f"{pct}% memory available ({avail} of {total} kB)"
    return res
def check_boot(runner, cfg) -> CheckResult:
    res = CheckResult("boot", PASS, "")
    boot_id = runner.run(["cat", "/proc/sys/kernel/random/boot_id"], timeout_s=cfg["timeout_s
"])
    uptime = runner.run(["cat", "/proc/uptime"], timeout_s=cfg["timeout_s"])
    kernel = runner.run(["uname", "-r"], timeout_s=cfg["timeout_s"])
    for r in (boot_id, uptime, kernel):
        res.add_evidence(r)
    if boot_id.ok:
        res.data["boot_id"] = boot_id.stdout.strip()
    if kernel.ok:
        res.data["kernel"] = kernel.stdout.strip()
    if uptime.ok and uptime.stdout.split():
        try:
            res.data["uptime_s"] = float(uptime.stdout.split()[0])
        except ValueError:
            pass
    if not res.data:
        res.status, res.detail = ERROR, "no boot information could be read"
        return res
    up = res.data.get("uptime_s")
    min_up = cfg.get("min_uptime_s", 0)
    if up is not None and up < min_up:
        res.status = WARN
        res.detail = f"recent reboot: uptime {up:.0f}s < {min_up}s"
    else:
        res.detail = f"kernel {res.data.get('kernel', '?')}, uptime {up if up is not None els
e '?'}s"
    return res
def check_logs(runner, cfg) -> CheckResult:
    res = CheckResult("logs", PASS, "")
    j = runner.run(["journalctl", "-b", "-p", "err", "--no-pager", "-q"], timeout_s=cfg["time
out_s"])
    k = runner.run(["dmesg"], timeout_s=cfg["timeout_s"])
    res.add_evidence(j, cfg.get("max_log_chars", 20000))
    res.add_evidence(k, cfg.get("max_log_chars", 20000))
    patterns = [re.compile(p, re.IGNORECASE) for p in cfg.get("kernel_error_patterns", [])]
    kernel_hits = []
    if k.ok:
        for line in k.stdout.splitlines():
            if any(p.search(line) for p in patterns):
                kernel_hits.append(line.strip())
    journal_errs = len(j.stdout.splitlines()) if j.ok else None
    res.data = {"journal_err_lines": journal_errs, "kernel_matches": kernel_hits[:50]}
    if not j.ok and not k.ok:
        res.status, res.detail = SKIP, "neither journal nor kernel log readable
(permissions?)"
    elif kernel_hits:
        res.status = WARN
        res.detail = f"{len(kernel_hits)} kernel line(s) match error patterns; first: {kernel
_hits[0][:120]}"
    elif journal_errs:
        res.status, res.detail = WARN, f"{journal_errs} err-level journal line(s) this boot"
    else:
        res.detail = "no matching errors found in readable logs"
    return res
def check_commands(runner, cfg) -> CheckResult:
    """Run the extra approved read-only commands listed in the config."""
    cmds = cfg.get("extra_commands", {})
      if not cmds:
          return CheckResult("extra_commands", SKIP, "none configured")
      res = CheckResult("extra_commands", PASS, "")
      failed = []
      for name, argv in cmds.items():
          r = runner.run(argv, timeout_s=cfg["timeout_s"])
          res.add_evidence(r)
          if not r.ok:
              failed.append(f"{name}({r.error or 'rc=' + str(r.returncode)})")
      if failed:
          res.status, res.detail = WARN, "some commands failed: " + ", ".join(failed)
      else:
          res.detail = f"{len(cmds)} command(s) collected"
      return res
  ALL_CHECKS: Dict[str, Callable] = {
      "connectivity": check_connectivity,
      "services": check_services,
      "disk": check_disk,
      "memory": check_memory,
      "boot": check_boot,
      "logs": check_logs,
      "extra_commands": check_commands,
  }
  def run_all(runner, cfg) -> List[CheckResult]:
      """Run the enabled checks; an exception in one check becomes an ERROR result."""
      results = []
      for name in cfg.get("enabled_checks", list(ALL_CHECKS)):
          func = ALL_CHECKS.get(name)
          if func is None:
              results.append(CheckResult(name, ERROR, "unknown check name"))
              continue
          t0 = time.monotonic()
          try:
              result = func(runner, cfg)
          except Exception as exc:  # noqa: BLE001 - deliberate: preserve other evidence
              log.exception("check %s crashed", name)
              result = CheckResult(name, ERROR, f"check crashed: {type(exc).__name__}: {exc}")
          result.duration_s = round(time.monotonic() - t0, 3)
          log.info("%s %s: %s", result.status, result.name, result.detail)
          results.append(result)
      return results
  def overall_status(results: List[CheckResult]) -> str:
      if not results:
          return ERROR
      return max((r.status for r in results), key=lambda s: SEVERITY.get(s, 3))
