class ConfigError(ValueError):
    pass
def _require(cond: bool, msg: str) -> None:
    if not cond:
        raise ConfigError(msg)
def validate(cfg: Dict[str, Any]) -> Dict[str, Any]:
    _require(isinstance(cfg["timeout_s"], (int, float)) and 0 < cfg["timeout_s"] <= 600,
             "timeout_s must be a number between 0 and 600")
    for key in ("disk_warn_pct", "disk_fail_pct", "mem_warn_available_pct",
                "mem_fail_available_pct"):
        _require(isinstance(cfg[key], int) and 0 <= cfg[key] <= 100, f"{key} must be 0-100")
    _require(cfg["disk_warn_pct"] <= cfg["disk_fail_pct"], "disk_warn_pct must be <=
disk_fail_pct")
    _require(cfg["mem_fail_available_pct"] <= cfg["mem_warn_available_pct"],
             "mem_fail_available_pct must be <= mem_warn_available_pct")
    for key in ("ping_hosts", "services", "enabled_checks", "kernel_error_patterns"):
        _require(isinstance(cfg[key], list) and all(isinstance(x, str) for x in cfg[key]),
                 f"{key} must be a list of strings")
    _require(isinstance(cfg["extra_commands"], dict), "extra_commands must be an object")
    for name, argv in cfg["extra_commands"].items():
        _require(isinstance(argv, list) and argv and all(isinstance(a, str) for a in argv),
                 f"extra_commands.{name} must be a non-empty list of strings (no shell
strings)")
    return cfg
def load(path: Optional[Path]) -> Dict[str, Any]:
    cfg = json.loads(json.dumps(DEFAULTS))  # deep copy
    if path is not None:
        try:
            user = json.loads(Path(path).read_text(encoding="utf-8"))
        except FileNotFoundError as exc:
            raise ConfigError(f"config file not found: {path}") from exc
        except json.JSONDecodeError as exc:
            raise ConfigError(f"invalid JSON in {path}: {exc}") from exc
        _require(isinstance(user, dict), "config root must be a JSON object")
        unknown = set(user) - set(DEFAULTS)
        _require(not unknown, f"unknown config keys: {sorted(unknown)}")
        cfg.update(user)
    return validate(cfg)
