  """JSON and human-readable report generation."""
  from __future__ import annotations
  import json
  import os
  import platform
  from dataclasses import asdict
  from pathlib import Path
  from typing import List
  from . import __version__
  from .checks import CheckResult, overall_status
  from .runner import utc_now
  def build_report(results: List[CheckResult], mode: str, target: str) -> dict:
      return {
          "tool": "linuxdiag",
          "version": __version__,
          "generated_utc": utc_now(),
          "mode": mode,                      # "real" or "simulated"
          "target": target,
          "collector_host": platform.node(),
          "overall": overall_status(results),
          "summary": {s: sum(1 for r in results if r.status == s)
                      for s in ("PASS", "WARN", "FAIL", "ERROR", "SKIP")},
          "checks": [asdict(r) for r in results],
      }
  def render_text(report: dict) -> str:
      lines = [
          "LINUX DIAGNOSTIC REPORT",
          "=" * 60,
          f"Generated : {report['generated_utc']}",
          f"Mode      : {report['mode']}"
          + ("   (SIMULATED DATA - not from a real device)" if report["mode"] == "simulated" el
  se ""),
          f"Target    : {report['target']}",
          f"Overall   : {report['overall']}",
          "Summary   : " + ", ".join(f"{k}={v}" for k, v in report["summary"].items()),
          "",
          f"{'CHECK':<16}{'STATUS':<8}{'TIME(s)':<9}DETAIL",
          "-" * 60,
      ]
      for c in report["checks"]:
          lines.append(f"{c['name']:<16}{c['status']:<8}{c['duration_s']:<9}{c['detail']}")
      lines.append("")
      lines.append("Evidence: see the JSON report for full command output.")
      return "\n".join(lines) + "\n"
  def write_reports(report: dict, outdir: Path) -> List[Path]:
      """Write report.json and report.txt atomically (write temp file, then rename)."""
      outdir.mkdir(parents=True, exist_ok=True)
      written = []
      for name, content in (("report.json", json.dumps(report, indent=2)),
                            ("report.txt", render_text(report))):
          final = outdir / name
          tmp = outdir / f".{name}.tmp"
          tmp.write_text(content, encoding="utf-8")
          os.replace(tmp, final)
          written.append(final)
      return written
