  """Command-line interface: python -m linuxdiag [options]."""
  from __future__ import annotations
  import argparse
  import logging
  import sys
  from datetime import datetime, timezone
  from pathlib import Path
  from typing import List, Optional
  from . import __version__, config
  from .checks import run_all
  from .report import build_report, render_text, write_reports
  from .runner import RealRunner, SimulatedRunner
  # Exit codes are part of the interface (used by Jenkins, Chapter 25).
  EXIT_OK, EXIT_WARN, EXIT_FAIL, EXIT_USAGE, EXIT_INFRA = 0, 0, 1, 2, 3
  def parse_args(argv: Optional[List[str]] = None) -> argparse.Namespace:
      p = argparse.ArgumentParser(prog="linuxdiag",
                                  description="Read-only Linux diagnostic collector")
      p.add_argument("-c", "--config", type=Path, help="JSON config file")
      p.add_argument("-o", "--outdir", type=Path, help="output directory for reports")
      p.add_argument("--simulate", type=Path, metavar="FIXTURE",
                     help="use simulated command output from a JSON fixture")
      p.add_argument("--target", default="localhost", help="label for the system under test")
      p.add_argument("--strict", action="store_true", help="treat WARN as failure (exit 1)")
      p.add_argument("-v", "--verbose", action="store_true")
      p.add_argument("--version", action="version", version=f"%(prog)s {__version__}")
      return p.parse_args(argv)
  def main(argv: Optional[List[str]] = None) -> int:
      args = parse_args(argv)
      logging.basicConfig(
          level=logging.DEBUG if args.verbose else logging.INFO,
          format="%(asctime)s %(levelname)-7s %(name)s: %(message)s",
          stream=sys.stderr,
      )
      log = logging.getLogger("linuxdiag")
      try:
          cfg = config.load(args.config)
      except config.ConfigError as exc:
          log.error("configuration error: %s", exc)
          return EXIT_USAGE
      if args.simulate:
          try:
              runner = SimulatedRunner.from_file(args.simulate)
          except (OSError, ValueError) as exc:
              log.error("cannot load simulation fixture: %s", exc)
              return EXIT_USAGE
          mode = "simulated"
      else:
          runner = RealRunner(timeout_s=cfg["timeout_s"])
          mode = "real"
      results = run_all(runner, cfg)
      report = build_report(results, mode, args.target)
      outdir = args.outdir or Path(f"diag_{datetime.now(timezone.utc):%Y%m%dT%H%M%SZ}")
      try:
          paths = write_reports(report, outdir)
      except OSError as exc:
          log.error("cannot write reports to %s: %s", outdir, exc)
          sys.stdout.write(render_text(report))   # don't lose the results
          return EXIT_INFRA
      sys.stdout.write(render_text(report))
      log.info("reports written: %s", ", ".join(str(p) for p in paths))
      overall = report["overall"]
      if overall in ("FAIL", "ERROR"):
          return EXIT_FAIL
      if overall == "WARN" and args.strict:
          return EXIT_FAIL
      return EXIT_OK
  if __name__ == "__main__":
      sys.exit(main())
