            axis { name 'PY';    values '3.12', '3.13' }
            axis { name 'SUITE'; values 'smoke', 'regression' }
        }
        agent { docker { image "python:${PY}-slim" } }      // Docker Pipeline plugin
        stages {
            stage('Test') {
                steps {
                    sh 'pip install -q -r requirements.txt'
                    sh 'python -m pytest -m "$SUITE" --junitxml=reports/junit-$PY-
$SUITE.xml'
