```code
"""Parse sensor readings in a simple, IPMI-like pipe-separated text format.
Example input line (synthetic, not taken from any real system):
    CPU0_Temp | 45.000 | degrees C | ok
"""
from __future__ import annotations
from dataclasses import dataclass
from typing import Iterable
class SensorParseError(ValueError):
    """Raised when a line cannot be parsed into a SensorReading."""
@dataclass(frozen=True)
class SensorReading:
    name: str
    value: float | None   # None when the sensor reports "na"
    unit: str
    status: str
def parse_line(line: str) -> SensorReading:
    parts = [p.strip() for p in line.split("|")]
    if len(parts) != 4:
        raise SensorParseError(f"expected 4 fields, got {len(parts)}: {line!r}")
    name, raw_value, unit, status = parts
    if not name:
        raise SensorParseError(f"empty sensor name: {line!r}")
    if raw_value.lower() == "na":
        value = None
    else:
        try:
            value = float(raw_value)
        except ValueError as exc:
            raise SensorParseError(f"bad value {raw_value!r} in {line!r}") from exc
    return SensorReading(name=name, value=value, unit=unit, status=status.lower())
def parse_text(text: str) -> list[SensorReading]:
    """Parse many lines. Blank lines and lines starting with '#' are ignored."""
    readings = []
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        readings.append(parse_line(line))
    return readings
def names(readings: Iterable[SensorReading]) -> list[str]:
    return [r.name for r in readings]
