```code
"""Evaluate sensor readings against configured thresholds."""
from __future__ import annotations
from dataclasses import dataclass
from .parser import SensorReading
@dataclass(frozen=True)
class Threshold:
    lower_critical: float | None = None
    upper_critical: float | None = None
def evaluate(reading: SensorReading, threshold: Threshold) -> str:
    """Return 'ok', 'critical' or 'unavailable'."""
    if reading.value is None:
        return "unavailable"
    if threshold.lower_critical is not None and reading.value < threshold.lower_critical:
        return "critical"
    if threshold.upper_critical is not None and reading.value > threshold.upper_critical:
        return "critical"
    return "ok"
def evaluate_all(readings: list[SensorReading],
                 thresholds: dict[str, Threshold]) -> dict[str, str]:
    """Evaluate every reading that has a threshold. Readings without one are skipped."""
    return {r.name: evaluate(r, thresholds[r.name]) for r in readings if r.name in
thresholds}
