```code
"""Tiny HTTP server exposing a Redfish-like API backed by SimulatedBMC.
Run:  python -m bmcsim.server --port 8000
Uses only the Python standard library. Binds to 127.0.0.1 by default.
Basic auth credentials are read from BMC_USER / BMC_PASSWORD (defaults are
simulator-only values; never reuse them on a real system).
"""
from __future__ import annotations
import argparse
import base64
import json
import os
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from .backend import SimulatedBMC
def make_handler(bmc: SimulatedBMC, user: str, password: str):
    expected = "Basic " + base64.b64encode(f"{user}:{password}".encode()).decode()
    s = bmc.state
    class Handler(BaseHTTPRequestHandler):
        server_version = "BMCSim/1.0"
        def log_message(self, fmt, *args):          # keep CI console quiet
            bmc.log("HTTP " + fmt % args)
        def _send(self, code: int, body: dict | None = None):
            data = json.dumps(body or {}).encode()
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)
        def _authorised(self) -> bool:
            if "auth_fail" in bmc.faults:
                return False
            return self.headers.get("Authorization") == expected
        def do_GET(self):
            path = self.path.rstrip("/")
            if path == "/redfish/v1":                 # service root is unauthenticated
in Redfish
                if "slow_root" in bmc.faults:
                    time.sleep(3)
                return self._send(200, {
                    "@odata.id": "/redfish/v1", "RedfishVersion": "1.17.0",
                    "Managers": {"@odata.id": "/redfish/v1/Managers"},
                    "Systems": {"@odata.id": "/redfish/v1/Systems"},
                    "Chassis": {"@odata.id": "/redfish/v1/Chassis"},
                })
            if not self._authorised():
                return self._send(401, {"error": "unauthorised"})
            m, sy, ch = s["manager_id"], s["system_id"], s["chassis_id"]
            routes = {
                f"/redfish/v1/Managers/{m}": lambda: {
                    "Id": m, "FirmwareVersion": s["firmware_version"],
                    "Status": {"State": "Enabled", "Health": "OK"}},
                f"/redfish/v1/Systems/{sy}": lambda: {
                    "Id": sy, "PowerState": s["power_state"]},
                f"/redfish/v1/Chassis/{ch}/Sensors": lambda: {
                    "Members": [{"@odata.id": f"/redfish/v1/Chassis/{ch}/Sensors/{n}"}
                                for n in s["sensors"]]},
                "/redfish/v1/UpdateService/FirmwareInventory": lambda: {
                    "Members": [{"@odata.id": "/redfish/v1/UpdateService/
FirmwareInventory/bmc_active"}]},
                "/redfish/v1/UpdateService/FirmwareInventory/bmc_active": lambda: {
                    "Id": "bmc_active", "Version": s["firmware_version"], "Updateable": T
rue},
            }
            prefix = f"/redfish/v1/Chassis/{ch}/Sensors/"
            if path.startswith(prefix) and path[len(prefix):] in s["sensors"]:
                name = path[len(prefix):]
                return self._send(200, {"Id": name, "Name": name, **s["sensors"][name]})
            if path in routes:
                return self._send(200, routes[path]())
            return self._send(404, {"error": f"not found: {path}"})
        def do_POST(self):
            if not self._authorised():
                return self._send(401, {"error": "unauthorised"})
            length = int(self.headers.get("Content-Length", 0))
            try:
                body = json.loads(self.rfile.read(length) or b"{}")
            except json.JSONDecodeError:
                return self._send(400, {"error": "invalid JSON"})
            if self.path == f"/redfish/v1/Systems/{s['system_id']}/Actions/
ComputerSystem.Reset":
                ok = bmc.set_power(body.get("ResetType", ""))
                return self._send(204 if ok else 400)
            return self._send(404, {"error": "not found"})
    return Handler
def main(argv=None) -> int:
    ap = argparse.ArgumentParser(description="Simulated Redfish BMC")
    ap.add_argument("--host", default="127.0.0.1")
    ap.add_argument("--port", type=int, default=8000)
    args = ap.parse_args(argv)
    bmc = SimulatedBMC()
    user = os.environ.get("BMC_USER", "sim-user")
    password = os.environ.get("BMC_PASSWORD", "sim-only-password")
    srv = ThreadingHTTPServer((args.host, args.port), make_handler(bmc, user, password))
    print(f"BMC simulator listening on http://{args.host}:{args.port} faults={sorted(bmc.
faults)}", flush=True)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        srv.server_close()
    return 0
if __name__ == "__main__":
    raise SystemExit(main())
```

```code
"""Minimal Redfish client used by the tests. Works against the simulator or,
in an authorised lab, against a real BMC that exposes the same standard paths."""
from __future__ import annotations
import requests
class BMCConnectionError(Exception):
    """BMC could not be reached (network, DNS, refused, timeout). Infrastructure, not
product."""
class BMCAuthError(Exception):
    """BMC rejected the credentials. Usually configuration, not product."""
class RedfishClient:
    def __init__(self, base_url: str, user: str, password: str,
                 timeout: float = 10.0, verify_tls: bool | str = True):
        self.base_url = base_url.rstrip("/")
        self.timeout = timeout
        self.session = requests.Session()
        self.session.auth = (user, password)
        self.session.verify = verify_tls
    def _request(self, method: str, path: str, **kw) -> requests.Response:
        url = f"{self.base_url}{path}"
        try:
            resp = self.session.request(method, url, timeout=self.timeout, **kw)
        except (requests.ConnectionError, requests.Timeout) as exc:
            raise BMCConnectionError(f"{method} {url}: {exc.__class__.__name__}") from
exc
        if resp.status_code == 401:
            raise BMCAuthError(f"{method} {url}: HTTP 401")
        return resp
    def get(self, path: str) -> dict:
        resp = self._request("GET", path)
        resp.raise_for_status()
        return resp.json()
    def post(self, path: str, payload: dict) -> requests.Response:
        return self._request("POST", path, json=payload)
    def close(self) -> None:
        self.session.close()
