// Project 2 - OpenBMC regression pipeline (simulation by default).
//
// Plugins: Pipeline, Git, JUnit, Workspace Cleanup, Timestamper, Credentials Binding.
// Lab mode additionally needs: Lockable Resources (lock step), a credential with
// ID 'bmc-lab-01-creds' (Username with password), and an agent labelled 'bmc-lab'
// that has network access to the lab BMC.  Nothing here flashes firmware.
def runPytest(String markerExpr) {
    // Returns pytest's exit code instead of failing the step, so reports are always
published.
    return sh(returnStatus: true, label: 'pytest', script: """#!/bin/bash
        . .venv/bin/activate
        python -m pytest ${markerExpr} \
            --junitxml=${env.REPORT_DIR}/junit.xml \
            --html=${env.REPORT_DIR}/report.html --self-contained-html \
            2>&1 | tee ${env.REPORT_DIR}/pytest-console.log
        exit \${PIPESTATUS[0]}
    """)
}
def suiteMarker(String suite) {
    switch (suite) {
        case 'smoke':      return "-m smoke"
        case 'regression': return "-m 'smoke or regression'"
        case 'full':       return ""
        default:           error("Unknown SUITE '${suite}'")
    }
}
def testStages() {
  try {
    stage('Health check') {
        def hc = sh(returnStatus: true, label: 'health check',
                    script: '. .venv/bin/activate && python scripts/health_check.py')
        if (hc != 0) {
            // Environment problem, not a product failure: stop before running tests.
            currentBuild.description = "Target not ready (health exit ${hc})"
            error("BMC health check failed with exit code ${hc} (10=unreachable 11=auth
12=unhealthy 13=config)")
        }
    }
    stage('Run tests') {
        def rc = runPytest(suiteMarker(params.SUITE ?: 'smoke'))   // params are null on
a job's first run
        echo "pytest exit code: ${rc}"
        if (rc == 1) {
            unstable("Test failures detected - see failure_summary.txt")
        } else if (rc != 0) {
            error("pytest did not complete normally (exit ${rc}) - pipeline/test-code
problem")
        }
    }
  } finally {
    // Runs on success AND failure, while credentials and the device lock are still held.
    stage('Collect diagnostics') {
        sh(returnStatus: true, label: 'collect logs',
           script: '. .venv/bin/activate && python scripts/collect_logs.py')
    }
  }
}
pipeline {
    agent { label "${params.TARGET == 'lab' ? 'bmc-lab' : 'linux && python3'}" }
    parameters {
        choice(name: 'SUITE',  choices: ['smoke', 'regression', 'full'], description: 'Wh
ich tests to run')
        choice(name: 'TARGET', choices: ['sim', 'lab'], description: 'sim = simulator
(default), lab = authorised lab BMC')
        string(name: 'EXPECTED_FW', defaultValue: '', description:
'Expected BMC firmware version (blank = value in config)')
        string(name: 'SIM_FAULTS',  defaultValue: '', description: 'Simulator only: e.g.
sensor_na,fan_critical')
    }
    options {
        timeout(time: 60, unit: 'MINUTES')
        timestamps()
        buildDiscarder(logRotator(numToKeepStr: '50', artifactNumToKeepStr: '20'))
    }
    environment {
        REPORT_DIR      = 'reports'
        ARTIFACT_DIR    = 'artifacts'
        TARGET_CONFIG   = "${params.TARGET == 'lab' ? 'config/lab-01.yaml' : 'config/
sim.yaml'}"
        EXPECTED_FW     = "${params.EXPECTED_FW ?: ''}"
        BMC_SIM_FAULTS  = "${params.TARGET == 'lab' ? '' : (params.SIM_FAULTS ?: '')}"
    }
    stages {
        stage('Checkout') {
            steps {
                checkout scm
                script {
                    env.GIT_SHORT = sh(returnStdout: true, script:
'git rev-parse --short HEAD').trim()
                    currentBuild.displayName = "#${env.BUILD_NUMBER} ${params.SUITE ?: 's
moke'}/${params.TARGET ?: 'sim'} @${env.GIT_SHORT}"
                }
            }
        }
        stage('Validate environment') {
            steps {
                sh 'rm -rf "$REPORT_DIR" "$ARTIFACT_DIR" && mkdir -p "$REPORT_DIR"
"$ARTIFACT_DIR"'
                sh 'bash scripts/env_check.sh'
            }
        }
        stage('Prepare Python') {
            steps {
                sh '''
                    python3 -m venv .venv
                    . .venv/bin/activate
                    python -m pip install --quiet -r requirements.txt
                    python -m pip freeze > "$ARTIFACT_DIR/pip-freeze.txt"
                '''
            }
        }
        stage('Pipeline self-test') {
            steps {
                sh '. .venv/bin/activate && python -m pytest -q selftest'
            }
        }
        stage('Test') {
            steps {
                script {
                    if (params.TARGET == 'lab') {
                        // Exclusive device access + credentials only inside this block.
                        lock(resource: 'bmc-lab-01') {
                            withCredentials([usernamePassword(credentialsId: 'bmc-lab-01-
creds',
                                    usernameVariable: 'BMC_USER', passwordVariable: 'BMC_
PASSWORD')]) {
                                testStages()
                            }
                        }
                    } else {
                        testStages()
                    }
                }
            }
        }
    }
    post {
        always {
            // Classification must never change the build result, so its exit code is
ignored.
            sh(returnStatus: true, script: '. .venv/bin/activate && python scripts/
classify_failures.py')
            junit testResults: 'reports/junit.xml', allowEmptyResults: true
            archiveArtifacts artifacts: 'reports/**, artifacts/**', allowEmptyArchive: tr
ue
        }
