```code
"""Exception hierarchy. Every framework error carries a failure *category*, so the
pipeline can tell product defects apart from lab or framework problems."""
from __future__ import annotations
class EtifError(Exception):
    category = "FRAMEWORK_ERROR"
class ConfigError(EtifError):
    category = "CONFIG_ERROR"
class DeviceUnavailableError(EtifError):
    """Device cannot be reached at all (network down, powered off, wrong address)."""
    category = "LAB_UNAVAILABLE"
class DeviceCommunicationError(EtifError):
    """Device was reachable but a transfer failed or timed out mid-operation."""
    category = "DEVICE_COMMUNICATION"
class AuthenticationError(EtifError):
    category = "AUTH_FAILURE"
class LockTimeoutError(EtifError):
    """Another job holds the device lock."""
    category = "LAB_UNAVAILABLE"
class CommandTimeoutError(DeviceCommunicationError):
    pass
class FirmwareUpdateError(EtifError):
    """The firmware update itself failed: a candidate product defect."""
    category = "FIRMWARE_REGRESSION"
class UnsupportedOperation(EtifError):
    category = "CONFIG_ERROR"
