from __future__ import annotations
import os
from dataclasses import dataclass, field
from pathlib import Path
import yaml
from .errors import ConfigError
VALID_ADAPTERS = {"simulated", "redfish"}
@dataclass
class TargetConfig:
    name: str
    adapter: str
    expected_firmware: str
    host: str | None = None
    port: int = 443
    verify_tls: bool | str = True
    request_timeout_s: float = 10.0
    command_timeout_s: float = 30.0
    ready_timeout_s: float = 300.0
    ssh_enabled: bool = False
    uart_device: str | None = None        # e.g. /dev/ttyUSB0 on the lab agent
    uart_baud: int = 115200
    allow_power_actions: bool = False
    allow_firmware_update: bool = False
    lock_dir: str = "/tmp/etif-locks"
    lock_timeout_s: float = 600.0
    sim: dict = field(default_factory=dict)   # simulator tuning (faults, delays)
    @property
    def is_simulated(self) -> bool:
        return self.adapter == "simulated"
    def credentials(self) -> tuple[str, str]:
        user, password = os.environ.get("DUT_USER"), os.environ.get("DUT_PASSWORD")
        if self.is_simulated:
            return user or "sim-user", password or "sim-only-password"
        if not user or not password:
            raise ConfigError("DUT_USER and DUT_PASSWORD must be set for a real target")
        return user, password
def load(path: str | os.PathLike | None = None) -> TargetConfig:
    path = Path(path or os.environ.get("ETIF_CONFIG", "config/sim.yaml"))
    if not path.is_file():
        raise ConfigError(f"config file not found: {path}")
    try:
        data = yaml.safe_load(path.read_text()) or {}
    except yaml.YAMLError as exc:
        raise ConfigError(f"{path}: invalid YAML: {exc}") from exc
    if any(k in data for k in ("password", "token", "secret")):
        raise ConfigError(f"{path}: secrets must not be stored in config files")
    unknown = set(data) - set(TargetConfig.__dataclass_fields__)
    if unknown:
        raise ConfigError(f"{path}: unknown keys {sorted(unknown)}")
    try:
        cfg = TargetConfig(**data)
    except TypeError as exc:
        raise ConfigError(f"{path}: {exc}") from exc
    if cfg.adapter not in VALID_ADAPTERS:
        raise ConfigError(f"{path}: adapter must be one of {sorted(VALID_ADAPTERS)}")
    if not cfg.is_simulated and not cfg.host:
        raise ConfigError(f"{path}: 'host' is required for adapter {cfg.adapter!r}")
    if os.environ.get("EXPECTED_FW"):
        cfg.expected_firmware = os.environ["EXPECTED_FW"]
    if os.environ.get("ETIF_SIM_FAULTS") and cfg.is_simulated:
        cfg.sim["faults"] = [f for f in os.environ["ETIF_SIM_FAULTS"].split(",") if f]
    return cfg
