```code
"""The adapter interface. Tests talk ONLY to this interface, never to a transport
directly, so the same test runs against the simulator or a lab device."""
from __future__ import annotations
import time
from abc import ABC, abstractmethod
from dataclasses import dataclass
from ..errors import DeviceUnavailableError, UnsupportedOperation
@dataclass
class CommandResult:
    command: str
    exit_code: int
    stdout: str
    stderr: str
    duration_s: float
class DeviceAdapter(ABC):
    def __init__(self, name: str):
        self.name = name
    # ---- required capabilities -------------------------------------------------
    @abstractmethod
    def is_reachable(self) -> bool: ...
    @abstractmethod
    def firmware_version(self) -> str: ...
    @abstractmethod
    def power_state(self) -> str: ...
    @abstractmethod
    def sensors(self) -> dict[str, dict]: ...
    @abstractmethod
    def reboot_bmc(self) -> None: ...
    # ---- optional capabilities (override when the transport supports them) ------
    def run_command(self, command: str, timeout_s: float) -> CommandResult:
        raise UnsupportedOperation(f"{type(self).__name__} cannot run shell commands")
    def console_log(self) -> str:
        return ""
    def start_firmware_update(self, image_path: str) -> str:
        raise UnsupportedOperation(f"{type(self).__name__} does not support firmware
update")
    def update_status(self, task_id: str) -> dict:
        raise UnsupportedOperation(f"{type(self).__name__} does not support firmware
update")
    def close(self) -> None:
        pass
    # ---- shared behaviour --------------------------------------------------------
    def wait_until_ready(self, timeout_s: float, poll_s: float = 2.0) -> float:
        """Poll until the device answers a real query. Returns seconds waited.
        Raises DeviceUnavailableError if the deadline passes (bounded wait)."""
        start = time.monotonic()
        last_error = "never reachable"
        while time.monotonic() - start < timeout_s:
            try:
                if self.is_reachable():
                    self.firmware_version()          # reachable AND serving requests
                    return time.monotonic() - start
            except Exception as exc:                 # noqa: BLE001 - keep polling
                last_error = f"{type(exc).__name__}: {exc}"
            time.sleep(poll_s)
        raise DeviceUnavailableError(
            f"{self.name} not ready after {timeout_s:.0f}s (last error: {last_error})")
