```code
"""Simulated device. Deterministic, fast, and able to inject faults, so the framework
and pipeline can be tested without hardware.
Faults (config 'sim: {faults: [...]}' or env ETIF_SIM_FAULTS):
  unreachable            device never answers
  no_ready_after_reboot  device does not come back after reboot_bmc()
  sensor_na              one sensor has no reading
  update_fails           firmware update ends in state 'Failed'
  update_hangs           firmware update never leaves 'Running'
  command_timeout        run_command() always times out
"""
from __future__ import annotations
import time
from ..errors import CommandTimeoutError, DeviceUnavailableError
from .base import CommandResult, DeviceAdapter
COMMANDS = {
    "uname -r": "6.6.0-sim-openbmc\n",
    "cat /etc/os-release": 'ID=openbmc-phosphor\nVERSION_ID="2.16.0-sim"\n',
    "uptime": " 10:00:00 up 0 min,  load average: 0.10, 0.05, 0.01\n",
    "systemctl is-system-running": "running\n",
}
class SimulatedDevice(DeviceAdapter):
    def __init__(self, name: str, firmware: str = "2.16.0-sim", faults=(),
                 reboot_s: float = 0.2, update_step_s: float = 0.05, next_firmware: str
= "2.17.0-sim"):
        super().__init__(name)
        self.faults = set(faults)
        self._fw = firmware
        self._next_fw = next_firmware
        self._reboot_s = reboot_s
        self._update_step_s = update_step_s
        self._down_until = 0.0
        self._power = "On"
        self._updates: dict[str, dict] = {}
        self._console: list[str] = [f"[    0.000000] Booting Linux on physical CPU 0x0
({name})",
                                    f"Phosphor OpenBMC (simulated) {firmware}", "login:"]
    def _now(self) -> float:
        return time.monotonic()
    def _check_up(self) -> None:
        if "unreachable" in self.faults or self._now() < self._down_until:
            raise DeviceUnavailableError(f"{self.name}: no response")
    # required -------------------------------------------------------------------
    def is_reachable(self) -> bool:
        try:
            self._check_up()
            return True
        except DeviceUnavailableError:
            return False
    def firmware_version(self) -> str:
        self._check_up()
        return self._fw
    def power_state(self) -> str:
        self._check_up()
        return self._power
    def sensors(self) -> dict[str, dict]:
        self._check_up()
        data = {
            "CPU0_Temp": {"reading": 45.0, "units": "Cel", "upper_critical": 95.0},
            "Inlet_Temp": {"reading": 24.5, "units": "Cel", "upper_critical": 45.0},
            "P12V": {"reading": 12.05, "units": "V", "lower_critical": 11.4, "upper_criti
cal": 12.6},
        }
        if "sensor_na" in self.faults:
            data["Inlet_Temp"]["reading"] = None
        return data
    def reboot_bmc(self) -> None:
        self._check_up()
        self._console += ["systemd[1]: Reached target Reboot.", "reboot: Restarting
system"]
        if "no_ready_after_reboot" in self.faults:
            self._down_until = float("inf")
        else:
            self._down_until = self._now() + self._reboot_s
            self._console += ["[    0.000000] Booting Linux on physical CPU 0x0", "login:
"]
    # optional -------------------------------------------------------------------
    def run_command(self, command: str, timeout_s: float) -> CommandResult:
        self._check_up()
        if "command_timeout" in self.faults:
            raise CommandTimeoutError(f"{self.name}: {command!r} timed out after {timeout
_s}s")
        if command in COMMANDS:
            return CommandResult(command, 0, COMMANDS[command], "", 0.01)
        return CommandResult(command, 127, "", f"sh: {command.split()[0]}: not found\n",
0.01)
    def console_log(self) -> str:
        return "\n".join(self._console) + "\n"
    def start_firmware_update(self, image_path: str) -> str:
        self._check_up()
        task_id = f"task-{len(self._updates) + 1}"
        self._updates[task_id] = {"started": self._now(), "image": image_path}
        self._console.append(f"phosphor-software-manager: activating {image_path}")
        return task_id
    def update_status(self, task_id: str) -> dict:
        self._check_up()
        task = self._updates[task_id]
        steps = (self._now() - task["started"]) / self._update_step_s
        if "update_hangs" in self.faults or steps < 4:
            return {"state": "Running", "percent": min(int(steps * 25), 75), "message": "
flashing"}
        if "update_fails" in self.faults:
            self._console.append("phosphor-software-manager: image verification FAILED")
            return {"state": "Failed", "percent": 100, "message": "image verification
failed"}
        if task.get("applied") is None:                 # apply once, then reboot
            task["applied"] = True
            self._fw = self._next_fw
            self.reboot_bmc()
        return {"state": "Completed", "percent": 100, "message": "update applied, BMC
rebooting"}
