```code
"""LAB ADAPTER - requires an authorised, reachable BMC that serves the DMTF Redfish API.
Not executed during the handbook's verification (no hardware was available).
Firmware update is intentionally NOT implemented here. Flashing is destructive and
platform-specific (HttpPushUri vs MultipartHttpPushUri, image signing, apply time,
recovery procedure). Implement it in your lab repository only after reading your
platform's documentation and agreeing a recovery plan - see handbook Chapter 24.
"""
from __future__ import annotations
import requests
from ..errors import AuthenticationError, DeviceCommunicationError,
DeviceUnavailableError
from .base import CommandResult, DeviceAdapter
class RedfishAdapter(DeviceAdapter):
    def __init__(self, name: str, base_url: str, user: str, password: str, timeout_s: flo
at = 10.0,
                 verify_tls: bool | str = True, manager_id: str = "bmc", system_id: str
= "system",
                 chassis_id: str = "chassis", ssh_runner=None):
        super().__init__(name)
        self.base_url = base_url.rstrip("/")
        self.timeout_s = timeout_s
        self.ids = {"manager": manager_id, "system": system_id, "chassis": chassis_id}
        self.ssh = ssh_runner
        self.session = requests.Session()
        self.session.auth = (user, password)
        self.session.verify = verify_tls
    def _get(self, path: str) -> dict:
        url = self.base_url + path
        try:
            resp = self.session.get(url, timeout=self.timeout_s)
        except requests.ConnectionError as exc:
            raise DeviceUnavailableError(f"GET {url}: {exc.__class__.__name__}") from exc
        except requests.Timeout as exc:
            raise DeviceCommunicationError(f"GET {url}: timeout after {self.timeout_s}s")
 from exc
        if resp.status_code in (401, 403):
            raise AuthenticationError(f"GET {url}: HTTP {resp.status_code}")
        if resp.status_code >= 400:
            raise DeviceCommunicationError(f"GET {url}: HTTP {resp.status_code}")
        return resp.json()
    def is_reachable(self) -> bool:
        try:
            self._get("/redfish/v1")
            return True
        except (DeviceUnavailableError, DeviceCommunicationError):
            return False
    def firmware_version(self) -> str:
        return self._get(f"/redfish/v1/Managers/{self.ids['manager']}")
["FirmwareVersion"]
    def power_state(self) -> str:
        return self._get(f"/redfish/v1/Systems/{self.ids['system']}")["PowerState"]
    def sensors(self) -> dict[str, dict]:
        coll = self._get(f"/redfish/v1/Chassis/{self.ids['chassis']}/Sensors")
        out = {}
        for member in coll.get("Members", []):
            s = self._get(member["@odata.id"])
            thresholds = s.get("Thresholds", {})
            out[s.get("Id", member["@odata.id"].rsplit("/", 1)[-1])] = {
                "reading": s.get("Reading"),
                "units": s.get("ReadingUnits"),
                "lower_critical": thresholds.get("LowerCritical", {}).get("Reading"),
                "upper_critical": thresholds.get("UpperCritical", {}).get("Reading"),
            }
        return out
    def reboot_bmc(self) -> None:
        url = f"{self.base_url}/redfish/v1/Managers/{self.ids['manager']}/Actions/
Manager.Reset"
        try:
            resp = self.session.post(url, json={"ResetType": "GracefulRestart"},
timeout=self.timeout_s)
        except requests.RequestException as exc:
            raise DeviceCommunicationError(f"POST {url}: {exc.__class__.__name__}") from
exc
        if resp.status_code not in (200, 202, 204):
            raise DeviceCommunicationError(f"POST {url}: HTTP {resp.status_code}")
    def run_command(self, command: str, timeout_s: float) -> CommandResult:
        if self.ssh is None:
            return super().run_command(command, timeout_s)
        return self.ssh.run(command, timeout_s)
    def close(self) -> None:
        self.session.close()
        if self.ssh:
            self.ssh.close()
