  import functools
  import json
  import logging
  import subprocess
  import time
  log = logging.getLogger(__name__)
  def retry(times=3, delay=2.0, backoff=2.0, exceptions=(Exception,)):
      """Retry a flaky *infrastructure* call (SSH connect, HTTP GET). Never wrap the assertion itself."""
      def deco(fn):
          @functools.wraps(fn)
          def wrapper(*args, **kwargs):
              wait = delay
              for attempt in range(1, times + 1):
                  try:
                      return fn(*args, **kwargs)
                  except exceptions as e:
                      if attempt == times:
                          raise
                      log.warning("%s failed (%s) attempt %d/%d, retry in %.1fs",
                                  fn.__name__, e, attempt, times, wait)
                      time.sleep(wait)
                      wait *= backoff
          return wrapper
      return deco
  def run(cmd, timeout=60):
      return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, check=True).stdout
@retry(times=30, delay=5, backoff=1, exceptions=(subprocess.CalledProcessError, subprocess.TimeoutExpired))
def wait_for_nvme(dev="/dev/nvme0"):
    run(["nvme", "id-ctrl", dev])            # succeeds only once the controller is live
def smart(dev="/dev/nvme0"):
    # JSON key names differ slightly across nvme-cli versions - verify on your version
    return json.loads(run(["nvme", "smart-log", dev, "-o", "json"]))
def power_cycle_loop(iterations, power_off, power_on, dev="/dev/nvme0", surprise=True):
    """power_off/power_on are callables for your PDU/relay/IPMI control [adapt]."""
    prev = smart(dev)
    with open("pc_results.jsonl", "a") as out:
        for i in range(1, iterations + 1):
            power_off(); time.sleep(10); power_on()
            wait_for_nvme(dev)
            cur = smart(dev)
            d_cycles = cur["power_cycles"] - prev["power_cycles"]
            d_unsafe = cur["unsafe_shutdowns"] - prev["unsafe_shutdowns"]
            ok = (d_cycles == 1 and d_unsafe == (1 if surprise else 0)
                  and cur["critical_warning"] == 0
                  and cur["media_errors"] == prev["media_errors"])
            out.write(json.dumps({"iter": i, "ok": ok, "d_cycles": d_cycles,
                                  "d_unsafe": d_unsafe, "cw": cur["critical_warning"]}) + "\n")
            out.flush()                       # a crash at iteration 900 keeps 899 results
            if not ok:
                log.error("Anomaly at iteration %d - stopping to preserve evidence", i)
                return False
            prev = cur
    return True
