        buildDiscarder(logRotator(numToKeepStr: '30'))
    }
    environment {
        BMC_CREDS = credentials('bmc-admin')    // exposes BMC_CREDS_USR / BMC_CREDS_PSW, masked
        PYTHONUNBUFFERED = '1'
    }
    stages {
        stage('Checkout') {
            steps { checkout scm }
        }
        stage('Setup') {
            steps {
                sh '''
                    python3 -m venv .venv
                    . .venv/bin/activate
                    pip install -q -r requirements.txt
                    mkdir -p reports logs
                '''
            }
        }
        stage('Test on DUT') {
            steps {
                lock(label: 'ast2600-dut', quantity: 1, variable: 'DUT') {
                    sh '''
                        . .venv/bin/activate
                        export BMC_USER="$BMC_CREDS_USR" BMC_PASS="$BMC_CREDS_PSW"
                        python3 tools/precheck.py --bmc "$DUT" || exit 3        # infra problem, not a test
failure
                        if [ "$SKIP_FLASH" != "true" ]; then
                            python3 tools/update_bmc.py --bmc "$DUT" --image "$FW_IMAGE" --wait-ready 900
                        fi
                        pytest -m "$SUITE" --bmc "$DUT" \
                               --junitxml=reports/junit.xml \
                               --html=reports/report.html --self-contained-html
                    '''
                }
            }
        }
    }
    post {
        always {
            junit allowEmptyResults: true, testResults: 'reports/*.xml'
            archiveArtifacts artifacts: 'reports/**,logs/**', allowEmptyArchive: true
        }
        failure {
            emailext to: 'bmc-val-team@example.com',
                     subject: "FAILED: ${env.JOB_NAME} #${env.BUILD_NUMBER} (${params.FW_IMAGE})",
                     body: "Console + reports: ${env.BUILD_URL}"
        }
        fixed {
            emailext to: 'bmc-val-team@example.com',
                     subject: "FIXED: ${env.JOB_NAME} #${env.BUILD_NUMBER}", body: "${env.BUILD_URL}"
        }
    }
}
```

Notes to say aloud: pytest exits 1 when tests fail. Because the junit step publishes the results, the build ends up red or UNSTABLE depending on the setup. The infrastructure pre-check exits 3, so the console shows clearly that the failure was environmental. If your team uses GitLab CI, the same concepts map to .gitlab-ci.yml stages, runners with tags, and artifacts:reports:junit . One BMC test-lead JD lists GitLab CI rather than Jenkins (Jabil JD).

