import functools
import time
def retry(times=3, exceptions=(Exception,), base_delay=0.1,
sleep=time.sleep):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(times):
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == times - 1:
                        raise
                    sleep(base_delay * 2 ** attempt)
        return wrapper
    return decorator

