from collections import OrderedDict
class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self._data = OrderedDict()
    def get(self, key):
        if key not in self._data:
            return None
        self._data.move_to_end(key)
        return self._data[key]
    def put(self, key, value):
        self._data[key] = value
        self._data.move_to_end(key)
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

class TokenBucket:
    def __init__(self, rate_per_s, capacity, clock):
        self.rate, self.capacity, self.clock = rate_per_s, capacity, clock
        self.tokens = capacity
        self.last = clock()
    def allow(self):
        now = self.clock()
        self.tokens = min(self.capacity, self.tokens + (now - self.last) * self.rate)
        self.last = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False

class CircuitBreaker:
    def __init__(self, max_failures, reset_after, clock):
        self.max_failures, self.reset_after, self.clock = max_failures, reset_after, clock
        self.failures = 0
        self.opened_at = None
    def call(self, func, *args):
        if self.opened_at is not None:
            if self.clock() - self.opened_at < self.reset_after:
                raise RuntimeError("circuit open")
            self.opened_at = None              # half-open: allow one trial
            self.failures = self.max_failures - 1
        try:
            result = func(*args)
        except Exception:
            self.failures += 1
            if self.failures >= self.max_failures:
                self.opened_at = self.clock()
            raise
        self.failures = 0
        return result

