from contextlib import contextmanager
_MISSING = object()
@contextmanager
def temporary_setting(device, key, value):
    original = device.get(key, _MISSING)
    device[key] = value
    try:
        yield device
    finally:
        if original is _MISSING:
            device.pop(key, None)
        else:
            device[key] = original

