def assign(jobs, devices):
    load = {d: 0 for d in devices}
    result = {}
    for job, tag in jobs:
        capable = [d for d, tags in devices.items() if tag in tags]
        if not capable:
            raise ValueError(f"no device for {job} ({tag})")
        chosen = min(capable, key=lambda d: (load[d], d))
        load[chosen] += 1
        result[job] = chosen
    return result

