def to_signed(raw, bits):
    if raw >= 1 << (bits - 1):
        raw -= 1 << bits
    return raw

def hexdump(data):
    lines = []
    for off in range(0, len(data), 16):
        chunk = data[off:off + 16]
        hexpart = " ".join(f"{b:02x}" for b in chunk)
        text = "".join(chr(b) if 32 <= b < 127 else "." for b in
chunk)
        lines.append(f"{off:08x}: {hexpart:<47}  {text}")
    return "\n".join(lines)

def crc8(data, poly=0x07, init=0x00):
    crc = init
    for byte in data:
        crc ^= byte
        for _ in range(8):
            crc = ((crc << 1) ^ poly) & 0xFF if crc & 0x80 else (crc
<< 1) & 0xFF
    return crc

import hashlib
import zlib
def verify_image(data, expected_crc):
    return (zlib.crc32(data) & 0xFFFFFFFF) == expected_crc
def sha256_hex(data):
    return hashlib.sha256(data).hexdigest()

START = 0x7E
def checksum(data):
    return (-sum(data)) & 0xFF
def build_frame(payload):
    if len(payload) > 255:
        raise ValueError("payload too long")
    body = bytes([len(payload)]) + payload
    return bytes([START]) + body + bytes([checksum(body)])
def parse_frames(stream):
    frames, i = [], 0
    while i < len(stream):
        if stream[i] != START or i + 2 > len(stream):
            i += 1
            continue
        length = stream[i + 1]
        end = i + 2 + length
        if end >= len(stream):
            break
        body = stream[i + 1:end]
        if checksum(body) == stream[end]:
            frames.append(stream[i + 2:end])
            i = end + 1
        else:
            i += 1
    return frames

def to_gray(n):
    return n ^ (n >> 1)
def from_gray(g):
    n = 0
    while g:
        n ^= g
        g >>= 1
    return n

def parse_i2cdetect(text):
    present, in_use = [], []
    for line in text.splitlines()[1:]:
        label, _, cells = line.partition(":")
        if not cells:
            continue
        base = int(label, 16)
        for col, cell in enumerate(cells.split()):
            addr = base + col
            if cell == "UU":
                in_use.append(addr)
            elif cell != "--":
                present.append(int(cell, 16))
    return {"present": present, "in_use": in_use}
